// ============================================================
// RULEBOOK – everything we know about each supplier.
// To add a supplier or change a rule, edit ONLY this node.
// FICTIONAL DEMO DATA (suppliers LUBRIKA / MAZOL / FILTRONIQ, customer VELOX).
// v3: long PDFs are read page by page + codePattern for the completeness check.
// ============================================================

const rulebook = {

  // Which OpenAI model reads the PDFs
  ai: {
    model: "gpt-6-luna",       // digital PDFs (text)
    modelScan: "gpt-6-luna",   // scans – switch to "gpt-6.1-sol" if scans are misread
    splitAbovePages: 4,        // PDFs longer than this are read one page at a time
    reviewScans: true,         // scans can't be checked against text -> always "Needs review"
  },

  // Same document uploaded as PDF and as Excel? Use only the Excel.
  preferExcelOverPdf: true,

  suppliers: {

    lubrika: {
      name: "LUBRIKA",
      identify: ["LUBRIKA"],
      docType: {
        OC: ["Auftragsbestätigung"],
        DN: ["Lieferschein"],
      },
      rules: {
        multiplyByPackSize: { OC: true, DN: false }, // boxes -> pieces on OC only
        litreLinesUnit: "L",                          // lines priced per litre (pos. 110)
        defaultUnit: "STK",                           // everything else is pieces
        stripLeadingZeros: true,                      // 0402370955 -> 402370955
      },
      // What a product code looks like in the text (used to check nothing was skipped)
      codePattern: "\\b4[0-4]\\d{4}\\b",                  // 410112, 420022 ...
      // What the AI must know about this supplier's documents
      aiNotes: `
- Order confirmation = "Auftragsbestätigung". Delivery note = "Lieferschein".
- Order confirmation: documentNumber = "Belegnummer"; poNumber = "Bestellnummer".
- Every position starts with the position number ("Posten": 10, 20, 30...) and the material number = supplierPartNo.
  "Materialnummer des Kunden" = customerPartNo.
- "Einheit" is the package (Karton, Bag in Box) -> unit.
- "Menge" is the NUMBER OF PACKAGES, not pieces -> quantity (e.g. "2,00").
- "Inhalt" is what one package contains -> packSize = only the count of pieces or litres:
  "10 X 1 l" -> "10", "4X4l" -> "4", "3X5l" -> "3", "20 l" -> "20".
- "Preis" -> unitPrice (e.g. "7,19") and priceUnit = the word after "pro" ("Stk" or "l").
- "Betrag EUR" -> lineTotal. Each position has its own "Lieferdatum" -> deliveryDate of that line.
- A position can continue on the next page: it is still ONE line.
- Delivery note: documentNumber = "Lieferscheinnummer" (keep leading zeros exactly as printed);
  poNumber = "Ihre Bestellung" or "Kundenbestellnr"; deliveryDate = "Lieferdatum";
  per line: supplierPartNo = "Material" or "Artikel"; quantity = number in "Menge" ("1 KAR" -> "1");
  unit = the package word ("Karton" / "KAR"); packSize from "Inhalt" ("10 CU" -> "10").`,
    },

    mazol: {
      name: "MAZOL",
      // Careful: the OC never prints "MAZOL", only "Detail objednávky"
      identify: ["MAZOL", "Detail objednávky"],
      docType: {
        OC: ["Detail objednávky"],
        DN: ["Dodací list"],
      },
      rules: {
        positionNumbering: "10-20-30",                // no positions printed
        priceWithVat: false,                          // use the price without VAT
        unitMap: { ks: "STK" },
      },
      codePattern: "\\b7\\d{4}\\b",                       // 70112, 70822 ...
      aiNotes: `
- Order confirmation = "Detail objednávky" (the supplier name is NOT printed on it). Delivery note = "Dodací list".
- Order confirmation: documentNumber = the number after "Detail objednávky č."; poNumber = the "PO..." number
  inside "Poznámka od zákazníka". There are no position numbers: position = null.
- supplierPartNo = "Kód". unit = "ks".
- "Dodáno / Objednáno" = delivered / ordered: "0ks / 4ks" -> confirmedQuantity "0", quantity "4".
- unitPrice = "Cena / (m. j.) bez DPH" (WITHOUT VAT). lineTotal = null ("Celkem" includes VAT).
- No delivery dates are printed: deliveryDate = null.
- Delivery note: documentNumber = number after "Dodací list č."; poNumber = number after "Objednávka č.";
  supplierPartNo = the number at the start of "Označení dodávky"; quantity from "Množství" ("4 ks" -> "4"), unit "ks".
  "Vystaveno" is the issue date, NOT a delivery date: deliveryDate = null.`,
    },

    filtroniq: {
      name: "FILTRONIQ",
      identify: ["FILTRONIQ"],
      docType: {
        OC: ["Proforma Invoice", "Unit price"],
        DN: ["Invoice specification", "Packing list"],
      },
      rules: {
        stripPoSuffix: true,                          // "PO8800000734 QWP" -> "PO8800000734"
        productCode: "customerPartNo",                // CF125 / FK 1107 (not the FQ index)
        mergeSameSkuAcrossPallets: false,             // one row per pallet
        unitMap: { SZ: "STK", pcs: "STK" },
      },
      codePattern: "\\b(?:[CAO]F\\d{3}|F[PK] \\d{3,4}[A-Z0-9/-]*)",  // CF125, FK 1119A-2X, FP 002/2
      aiNotes: `
- Order confirmation = "Proforma Invoice for order ...". Delivery note = "Invoice specification".
- Order confirmation: documentNumber = the number after "Proforma Invoice for order"; poNumber = after
  "Customer Order Number"; position = "No"; customerPartNo = "Part No"; unit = "Unit";
  unitPrice = "Discount Unit Price"; lineTotal = "Total Amount".
- Delivery note: one line per row; palletNo = "Pallet No"; customerPartNo = "Customer Part No";
  poNumber of the LINE = "Reference". The reference is often split over two text lines
  ("PO88000006" then "61") – join them into one ("PO8800000661").`,
      // How their Excel files are laid out.
      // Column titles must be written exactly as in the file.
      excel: {
        OC: {
          docNumberLabel: "Invoice no:",
          columns: {
            position: "No.",
            customerPartNo: "Part No/Indeks Klienta",
            supplierPartNo: "Part no/Indeks",
            quantity: "Qty/Ilość",
            unit: "Unit/JM",
            unitPrice: "Discount price/Cena po rabacie",
            lineTotal: "Value Net/Wartość netto",
            poNumber: "Customer order no/Nr zamówienia klienta",
          },
        },
        DN: {
          docNumberLabel: "Packing list for the invoice no:",
          columns: {
            palletNo: "Pallet no",
            customerPartNo: "Customer Part No",
            supplierPartNo: "FILTRONIQ part no",
            quantity: "Quantity",
            unit: "UM",
            poNumber: "Reference",
          },
        },
      },
    },
  },

  // How the output Excel must look
  output: {
    dateFormat: "YYYY-MM-DD",
    decimalSeparator: ",",
    // Column order exactly as in the templates
    columns: {
      OC: [
        "DOCUMENTNUMBER", "BUYERREFERENCE", "POSITIONNUMBER",
        "CONFIRMEDPRODUCTIDEXTERNAL", "REJECTED", "SUBSTITUTEPRODUCTIDEXTERNAL",
        "CONFIRMEDDLVDATE", "CONFIRMEDQUANTITY", "CONFIRMEDQUANTITYUOM",
        "PRICE", "COSTPRICE", "INFODATE", "QUANTITY", "DOCUMENTTYPE",
      ],
      DN: [
        "PACKINGSLIPID", "ESTIMATEDARRIVALDATETIME", "LICENSEPLATENUMBER",
        "PURCHASEORDERNUMBER", "EXTERNALITEMID", "QUANTITY", "UNITSYMBOL",
      ],
    },
  },
};

// Pass the uploaded files through untouched, and attach the rulebook.
return [
  {
    json: { rulebook },
    binary: $input.first().binary,
  },
];

// ============================================================
// SPLIT FILES – turns "one item with many files" into "one item per file".
// v2: a PDF that also exists as Excel (same name) is marked "duplicate"
//     and is not sent to the AI – the Excel is read exactly, at no cost.
// ============================================================

const rulebook = $('RULEBOOK').first().json.rulebook;

// All uploaded files, as they arrive: Documents_0, Documents_1, ...
const files = $input.first().binary;

// The empty list we'll fill with one item per file
const output = [];

// Go through the files one by one
for (const key of Object.keys(files)) {
  const file = files[key];

  // File extension in lowercase (LUBRIKA sends ".PDF" in capitals)
  const ext = (file.fileExtension || "").toLowerCase();

  // Label the file by its extension
  let fileKind = "unknown";
  if (ext === "pdf") fileKind = "pdf";
  if (ext === "xls" || ext === "xlsx") fileKind = "excel";

  // Add one item for this file
  output.push({
    json: {
      fileName: file.fileName,
      fileKind: fileKind,
    },
    binary: {
      data: file, // every file now travels under the same name: "data"
    },
  });
}

// A PDF with an Excel twin (same name, other extension) -> "duplicate"
if (rulebook.preferExcelOverPdf) {
  const baseName = name => name.replace(/\.[^.]+$/, "").toLowerCase();
  const excelNames = output
    .filter(item => item.json.fileKind === "excel")
    .map(item => baseName(item.json.fileName));
  for (const item of output) {
    if (item.json.fileKind === "pdf" && excelNames.includes(baseName(item.json.fileName))) {
      item.json.fileKind = "duplicate";
    }
  }
}

return output;

// ============================================================
// DIGITAL OR SCANNED? – v2: the text arrives page by page ("Join Pages" off).
// Counts the characters; a scan is only a picture, so ~0 characters.
// ============================================================

// With "Join Pages" off, n8n gives a list: one text per page
const pages = Array.isArray($json.text) ? $json.text.map(t => String(t || "")) : [String($json.text || "")];
const text = pages.join("\n\n");

// Remove spaces and line breaks, count only real characters
const charCount = text.replace(/\s/g, "").length;

// Under 100 real characters = no usable text layer, so it is a scan
const pdfType = charCount > 100 ? "digital" : "scanned";

return {
  json: {
    fileName: $('Split files').item.json.fileName,
    pdfType: pdfType,
    charCount: charCount,
    pageCount: $json.numpages || pages.length,
    pages: pages,      // the text of each page, separately
    text: text,        // all pages together
  },
  binary: $('Split files').item.binary,
};

// ============================================================
// READ EXCEL – turn supplier Excel rows into standard lines.
// Reads the layout from RULEBOOK, so new Excel suppliers need no new code.
// ============================================================

const rulebook = $('RULEBOOK').first().json.rulebook;
const items = $input.all();

// ---------- Helpers ----------

// One Excel row -> a simple list of cells
function toCells(json) {
  const values = Object.values(json);
  if (values.length === 1 && Array.isArray(values[0])) return values[0];
  return values;
}

// A cell as lowercase text without spaces at the ends (for comparing)
function clean(value) {
  return String(value ?? "").trim().toLowerCase();
}

// Which supplier? Looks for the RULEBOOK "identify" words
function findSupplier(text) {
  for (const [key, s] of Object.entries(rulebook.suppliers)) {
    if (s.identify.some(word => text.includes(word.toLowerCase()))) return key;
  }
  return null;
}

// OC or DN? Looks for the RULEBOOK "docType" words
function findDocType(text, supplier) {
  for (const [type, words] of Object.entries(supplier.docType)) {
    if (words.some(word => text.includes(word.toLowerCase()))) return type;
  }
  return null;
}

// ---------- 1. Group the rows by the file they came from ----------
const files = {};
items.forEach((item, i) => {
  const fileName = $('Split files').itemMatching(i).json.fileName;
  if (!files[fileName]) files[fileName] = [];
  files[fileName].push(toCells(item.json));
});

// ---------- 2. Read each file ----------
const output = [];

for (const [fileName, rows] of Object.entries(files)) {
  const allText = rows.map(r => r.join(" ")).join(" ").toLowerCase();

  // Supplier
  const supplierKey = findSupplier(allText);
  if (!supplierKey) {
    output.push({ json: { sourceFile: fileName, status: "Unknown supplier" } });
    continue;
  }
  const supplier = rulebook.suppliers[supplierKey];

  // Document type + its Excel layout from RULEBOOK
  const docType = findDocType(allText, supplier);
  const layout = supplier.excel?.[docType];
  if (!layout) {
    output.push({ json: { sourceFile: fileName, supplierName: supplier.name,
                          status: "Unknown document type in Excel" } });
    continue;
  }

  // Document number: the first filled cell after its label
  let documentNumber = null;
  for (const row of rows) {
    const idx = row.findIndex(c => clean(c) === clean(layout.docNumberLabel));
    if (idx >= 0) {
      documentNumber = row.slice(idx + 1).find(c => clean(c) !== "") ?? null;
      break;
    }
  }

  // Header row: the row that contains the PO column title
  const headerIndex = rows.findIndex(row =>
    row.some(c => clean(c) === clean(layout.columns.poNumber)));
  if (headerIndex < 0) {
    output.push({ json: { sourceFile: fileName, supplierName: supplier.name,
                          status: "Table header not found" } });
    continue;
  }
  const header = rows[headerIndex].map(clean);

  // Which column number each field sits in
  const col = {};
  for (const [field, title] of Object.entries(layout.columns)) {
    col[field] = header.indexOf(clean(title));
  }
  const get = (row, field) => (col[field] >= 0 ? row[col[field]] : null);

  // The lines under the header
  for (const row of rows.slice(headerIndex + 1)) {
    const code = get(row, "customerPartNo") || get(row, "supplierPartNo");
    const quantity = get(row, "quantity");
    if (clean(code) === "" || isNaN(parseFloat(quantity))) continue; // empty or total row

    output.push({
      json: {
        sourceFile: fileName,
        supplier: supplierKey,
        supplierName: supplier.name,
        docType: docType,
        documentNumber: documentNumber != null ? String(documentNumber) : null,
        poNumber: get(row, "poNumber"),
        position: get(row, "position"),
        customerPartNo: get(row, "customerPartNo"),
        supplierPartNo: get(row, "supplierPartNo"),
        quantity: quantity,
        unit: get(row, "unit"),
        unitPrice: get(row, "unitPrice"),
        lineTotal: get(row, "lineTotal"),
        palletNo: get(row, "palletNo"),
        status: "OK",
      },
    });
  }
}

return output;

// ============================================================
// APPLY RULES – RULEBOOK rules + checks, line by line.
// v2: litre lines, defaultUnit, printed confirmed quantity (for the PDF road).
// v3: also passes on the notes of the AI completeness check (checkNote).
// In:  standard lines (from any road: Excel, PDF, scan)
// Out: per line -> the template row + a review note
// ============================================================

const rulebook = $('RULEBOOK').first().json.rulebook;
const dec = rulebook.output.decimalSeparator;

// ---------- Helpers ----------

// Read a number from anything: 60, "60.0", "2,00", "1.183,73", "2 463,76"
function toNumber(value) {
  if (value === null || value === undefined || value === "") return null;
  if (typeof value === "number") return value;
  let s = String(value).replace(/\s/g, "");
  if (s.includes(",")) s = s.replace(/\./g, "").replace(",", ".");
  const n = parseFloat(s);
  return isNaN(n) ? null : n;
}

// Write a number the way the template wants it: 7.19 -> "7,19", 60 -> "60"
function formatNumber(n) {
  if (n === null || n === undefined) return "";
  return String(parseFloat(n.toFixed(4))).replace(".", dec);
}

// "15.10.2026" -> "2026-10-15"; "2026-10-15" stays as it is
function toIsoDate(value) {
  if (!value) return "";
  const s = String(value).trim();
  const m = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
  if (m) return `${m[3]}-${m[2].padStart(2, "0")}-${m[1].padStart(2, "0")}`;
  return s;
}

// ---------- Apply the rules ----------
const output = [];
const positionCounter = {}; // for suppliers that print no position numbers

for (const item of $input.all()) {
  const line = item.json;

  // Files we couldn't read: they only go to the review sheet
  if (line.status !== "OK") {
    output.push({ json: { template: null, row: null, review: {
      sourceFile: line.sourceFile, supplier: line.supplierName || "",
      docType: "", documentNumber: "", position: "", productCode: "",
      status: "Needs review", reason: line.status } } });
    continue;
  }

  const rules = rulebook.suppliers[line.supplier].rules || {};
  const notes = []; // reasons this line needs a human look
  if (line.checkNote) notes.push(line.checkNote); // from the AI checks (missing/invented code, scan)

  // Document number – remove leading zeros if the rule says so
  let documentNumber = String(line.documentNumber ?? "").trim();
  if (rules.stripLeadingZeros) documentNumber = documentNumber.replace(/^0+/, "");

  // PO number – cut suffixes like " QWP" if the rule says so
  let poNumber = String(line.poNumber ?? "").trim();
  if (rules.stripPoSuffix) poNumber = poNumber.split(/\s+/)[0];

  // Product code – the one RULEBOOK says to use
  const productCode = String(line[rules.productCode || "supplierPartNo"] ?? "").trim();

  // Unit – in this order:
  //  1. line priced per litre + rule litreLinesUnit -> "L"
  //  2. unitMap translation (SZ -> STK, ks -> STK), ignoring capitals
  //  3. the supplier's defaultUnit (LUBRIKA: Karton -> STK)
  //  4. otherwise the printed unit in capitals
  const rawUnit = String(line.unit ?? "").trim();
  const perLitre = /^(l|liter|litre|ltr)$/i.test(String(line.priceUnit ?? "").trim());
  const mapKey = Object.keys(rules.unitMap || {})
    .find(k => k.toLowerCase() === rawUnit.toLowerCase());
  let unit;
  if (perLitre && rules.litreLinesUnit) unit = rules.litreLinesUnit;
  else if (mapKey) unit = rules.unitMap[mapKey];
  else if (rules.defaultUnit) unit = rules.defaultUnit;
  else unit = rawUnit.toUpperCase();

  // Quantity – as printed, and converted (boxes -> pieces) if the rule says so
  const printedQty = toNumber(line.quantity);
  const packSize = toNumber(line.packSize);
  let confirmedQty = printedQty;
  if (rules.multiplyByPackSize?.[line.docType] && packSize && printedQty !== null) {
    confirmedQty = printedQty * packSize;
  }
  // The document prints a confirmed quantity of its own (MAZOL "0ks / 4ks")? That one wins.
  const printedConfirmed = toNumber(line.confirmedQuantity);
  if (printedConfirmed !== null) confirmedQty = printedConfirmed;

  // Position – as printed, or numbered 10-20-30 when the supplier prints none
  let position = line.position;
  if (position === null || position === undefined || position === "") {
    positionCounter[line.sourceFile] = (positionCounter[line.sourceFile] || 0) + 1;
    const n = positionCounter[line.sourceFile];
    position = rules.positionNumbering === "10-20-30" ? n * 10 : n;
  }
  position = formatNumber(toNumber(position));

  const unitPrice = toNumber(line.unitPrice);
  const lineTotal = toNumber(line.lineTotal);

  // ---------- Checks ----------
  if (!documentNumber) notes.push("Document number missing");
  if (!productCode) notes.push("Product code missing");
  if (confirmedQty === null) notes.push("Quantity missing");
  if (line.docType === "OC" && unitPrice !== null && lineTotal !== null && confirmedQty !== null) {
    const expected = confirmedQty * unitPrice;
    if (Math.abs(expected - lineTotal) > 0.02) {
      notes.push(`Quantity x price = ${formatNumber(expected)}, but the line total is ${formatNumber(lineTotal)}`);
    }
  }

  // ---------- The template row, with the template's exact column names ----------
  let row;
  if (line.docType === "OC") {
    row = {
      DOCUMENTNUMBER: documentNumber,
      BUYERREFERENCE: poNumber,
      POSITIONNUMBER: position,
      CONFIRMEDPRODUCTIDEXTERNAL: productCode,
      REJECTED: "",
      SUBSTITUTEPRODUCTIDEXTERNAL: "",
      CONFIRMEDDLVDATE: toIsoDate(line.deliveryDate),
      CONFIRMEDQUANTITY: formatNumber(confirmedQty),
      CONFIRMEDQUANTITYUOM: unit,
      PRICE: formatNumber(unitPrice),
      COSTPRICE: "",
      INFODATE: "",
      QUANTITY: formatNumber(printedQty),
      DOCUMENTTYPE: "OrderResponse",
    };
  } else {
    row = {
      PACKINGSLIPID: documentNumber,
      ESTIMATEDARRIVALDATETIME: toIsoDate(line.deliveryDate),
      LICENSEPLATENUMBER: line.licensePlate || "",
      PURCHASEORDERNUMBER: poNumber,
      EXTERNALITEMID: productCode,
      QUANTITY: formatNumber(confirmedQty),
      UNITSYMBOL: unit,
    };
  }

  output.push({
    json: {
      template: line.docType,
      row: row,
      review: {
        sourceFile: line.sourceFile,
        supplier: line.supplierName,
        docType: line.docType,
        documentNumber: documentNumber,
        position: position,
        productCode: productCode,
        status: notes.length ? "Needs review" : "OK",
        reason: notes.join("; "),
      },
    },
  });
}

return output;

// ============================================================
// TEMPLATE ROWS – keep one document type, only the template columns,
// in the template's order.
// ============================================================

const TYPE = "OC"; // <- in the DN copy of this node, write "DN"

const columns = $('RULEBOOK').first().json.rulebook.output.columns[TYPE];

const rows = $input.all()
  .filter(item => item.json.template === TYPE)
  .map(item => {
    const ordered = {};
    for (const c of columns) ordered[c] = item.json.row[c] ?? "";
    return { json: ordered };
  });

// None of this type in the upload? One empty row, so the file still gets made
if (rows.length === 0) {
  const empty = {};
  for (const c of columns) empty[c] = "";
  return [{ json: empty }];
}

return rows;

// ============================================================
// TEMPLATE ROWS – keep one document type, only the template columns,
// in the template's order.
// ============================================================

const TYPE = "DN"; 

const columns = $('RULEBOOK').first().json.rulebook.output.columns[TYPE];

const rows = $input.all()
  .filter(item => item.json.template === TYPE)
  .map(item => {
    const ordered = {};
    for (const c of columns) ordered[c] = item.json.row[c] ?? "";
    return { json: ordered };
  });

// None of this type in the upload? One empty row, so the file still gets made
if (rows.length === 0) {
  const empty = {};
  for (const c of columns) empty[c] = "";
  return [{ json: empty }];
}

return rows;

// ============================================================
// REVIEW ROWS – the review file.
// Only the lines that need a human look, with the reason.
// ============================================================

const rows = $input.all().map(item => {
  const r = item.json.review;
  return {
    json: {
      "Status": r.status,
      "Reason": r.reason,
      "Source file": r.sourceFile,
      "Supplier": r.supplier,
      "Document type": r.docType,
      "Document no.": r.documentNumber,
      "Position": r.position,
      "Product code": r.productCode,
    },
  };
});

// Keep only the lines that need a human look
const toCheck = rows.filter(r => r.json.Status !== "OK");

// Nothing to check? One row that says so, so the file isn't empty
if (toCheck.length === 0) {
  return [{ json: { "Status": "OK", "Reason": "All lines are OK" } }];
}

return toCheck;

// ============================================================
// BUNDLE FILES – the 3 files from 3 items -> into 1 item,
// because the Zip node packs files that sit in the same item.
// ============================================================

const binary = {};
$input.all().forEach((item, i) => {
  binary[`file_${i}`] = item.binary.data;
});

return [{ json: {}, binary }];

// ============================================================
// BUILD AI REQUEST – v2. Builds the questions for OpenAI.
//  - short digital PDF  -> 1 question with all its text
//  - long digital PDF   -> 1 question PER PAGE (more than RULEBOOK ai.splitAbovePages)
//  - scan               -> 1 question with the PDF file itself
// The AI only COPIES what is printed; the rules in RULEBOOK do the maths later.
// MODE: Run Once for All Items
// ============================================================

const rulebook = $('RULEBOOK').first().json.rulebook;
const items = $input.all();
const output = [];

// ---------- The fixed answer format (OpenAI must follow it exactly) ----------
const str = { type: ["string", "null"] };
const lineFields = {
  position: str, supplierPartNo: str, customerPartNo: str, description: str,
  poNumber: str, quantity: str, confirmedQuantity: str, unit: str, packSize: str,
  unitPrice: str, priceUnit: str, lineTotal: str, deliveryDate: str, palletNo: str,
};
const schema = {
  type: "object",
  additionalProperties: false,
  required: ["supplier", "docType", "documentNumber", "poNumber", "deliveryDate", "lines"],
  properties: {
    supplier: { type: "string", enum: [...Object.keys(rulebook.suppliers), "unknown"] },
    docType: { type: "string", enum: ["OC", "DN", "unknown"] },
    documentNumber: str,
    poNumber: str,
    deliveryDate: str,
    lines: {
      type: "array",
      items: { type: "object", additionalProperties: false, required: Object.keys(lineFields), properties: lineFields },
    },
  },
};

// ---------- The instructions, with the notes of the supplier(s) ----------
function instructionsFor(keys) {
  const notes = keys
    .map(k => `### Supplier "${k}" (${rulebook.suppliers[k].name})${rulebook.suppliers[k].aiNotes || ""}`)
    .join("\n\n");
  return `You read order confirmations (OC) and delivery notes (DN) sent by suppliers
to a car-parts distributor, and you copy their content into a fixed JSON format.

RULES
1. Copy values EXACTLY as printed. Do not calculate, convert or round anything.
   Numbers stay as printed text, with their own decimal comma ("7,19", "2,00", "2 463,76").
   Dates stay as printed ("15.10.2026").
2. One entry in "lines" for EVERY product line you are given, in the order printed. Do not stop early.
   A line that continues on the next page is still one line. Skip totals, VAT and note rows.
3. If a value is not printed, use null. Never invent a value.
4. "supplier" must be one of the supplier keys below; if none fits, use "unknown".
5. "docType": "OC" for an order confirmation, "DN" for a delivery note, "unknown" otherwise.
6. Put a value on the line ("poNumber", "deliveryDate") only when it is printed on that line;
   values printed once for the whole document go in the document-level fields.

SUPPLIER NOTES
${notes}`;
}

// ---------- One request ----------
function request({ fileName, supplierKey, isScan, part, parts, pageText, content, keys }) {
  return {
    fileName, supplierKey, isScan, part, parts,
    pageText,   // the text this request covers – used later to check nothing was skipped
    body: {
      model: isScan ? rulebook.ai.modelScan : rulebook.ai.model,
      instructions: instructionsFor(keys),
      input: [{ role: "user", content }],
      text: { format: { type: "json_schema", name: "supplier_document", strict: true, schema } },
    },
  };
}

// ---------- Go through the PDFs ----------
for (let index = 0; index < items.length; index++) {
  const doc = items[index].json;
  const fileName = doc.fileName;
  const isScan = doc.pdfType === "scanned";
  const pages = doc.pages || [doc.text || ""];
  const lower = (doc.text || "").toLowerCase();

  // Which supplier? (only possible when there is text)
  let supplierKey = null;
  for (const [key, s] of Object.entries(rulebook.suppliers)) {
    if (s.identify.some(word => lower.includes(word.toLowerCase()))) { supplierKey = key; break; }
  }
  const keys = supplierKey ? [supplierKey] : Object.keys(rulebook.suppliers);

  if (isScan) {
    // Scan: send the PDF file itself
    const buffer = await this.helpers.getBinaryDataBuffer(index, "data");
    output.push({
      json: request({
        fileName, supplierKey, isScan, part: 1, parts: 1, pageText: "", keys,
        content: [
          { type: "input_file", filename: fileName, file_data: `data:application/pdf;base64,${buffer.toString("base64")}` },
          { type: "input_text", text: "Copy this document into the JSON format." },
        ],
      }),
      pairedItem: { item: index },
    });
  } else if (pages.length > (rulebook.ai.splitAbovePages || 999)) {
    // Long document: one request per page
    pages.forEach((pageText, p) => {
      output.push({
        json: request({
          fileName, supplierKey, isScan, part: p + 1, parts: pages.length, pageText, keys,
          content: [
            { type: "input_text", text: `DOCUMENT TEXT (${fileName}) – PAGE ${p + 1} OF ${pages.length}:\n\n${pageText}` },
            { type: "input_text", text: `Copy ONLY the product lines printed on this page. Document-level fields: fill them only if they are printed on this page, otherwise null.` },
          ],
        }),
        pairedItem: { item: index },
      });
    });
  } else {
    // Short document: one request with all its text
    output.push({
      json: request({
        fileName, supplierKey, isScan, part: 1, parts: 1, pageText: doc.text, keys,
        content: [
          { type: "input_text", text: `DOCUMENT TEXT (${fileName}):\n\n${doc.text}` },
          { type: "input_text", text: "Copy this document into the JSON format." },
        ],
      }),
      pairedItem: { item: index },
    });
  }
}

return output;

// ============================================================
// READ AI ANSWER – v2
//  1. glues the pages of one document back together
//  2. checks, in code, that NO product line was skipped or invented:
//     every product code found in the page text must be in the AI's answer, and
//     every code in the AI's answer must be in the page text (RULEBOOK codePattern)
//  3. turns everything into standard lines (same shape as "Read Excel")
// ============================================================

const rulebook = $('RULEBOOK').first().json.rulebook;
const output = [];
const norm = c => String(c ?? "").replace(/\s+/g, " ").trim().toUpperCase();
const problem = (fileName, reason) => output.push({ json: { sourceFile: fileName, status: reason } });

// ---------- 1. Read every answer, group the pages per document ----------
const docs = {}; // fileName -> list of parts
$input.all().forEach((item, i) => {
  const req = $('Build AI request').itemMatching(i).json;
  const part = { req, answer: null, error: null };

  if (item.json.error) {
    part.error = `OpenAI error: ${item.json.error.message || JSON.stringify(item.json.error)}`;
  } else if (item.json.status && item.json.status !== "completed") {
    part.error = `Incomplete AI answer (${item.json.status})`;
  } else {
    const message = (item.json.output || []).find(o => o.type === "message");
    const textPart = message && (message.content || []).find(c => c.type === "output_text");
    try {
      part.answer = JSON.parse(textPart.text);
    } catch (e) {
      part.error = "Invalid or empty AI answer";
    }
  }
  (docs[req.fileName] = docs[req.fileName] || []).push(part);
});

// ---------- 2. Each document ----------
for (const [fileName, parts] of Object.entries(docs)) {
  parts.sort((a, b) => a.req.part - b.req.part);
  const first = parts[0].req;
  const pageLabel = p => (p.req.parts > 1 ? `page ${p.req.part}: ` : "");

  // Pages that failed are reported; the good pages still count
  parts.filter(p => p.error).forEach(p => problem(fileName, `${pageLabel(p)}${p.error}`));
  const good = parts.filter(p => p.answer);
  if (good.length === 0) continue;

  // Document-level fields: the first page that prints them
  const pick = field => (good.find(p => p.answer[field] && p.answer[field] !== "unknown") || {}).answer?.[field] ?? null;
  const supplierKey = first.supplierKey || pick("supplier");
  const supplier = rulebook.suppliers[supplierKey];
  const docType = pick("docType");
  if (!supplier) { problem(fileName, "Unknown supplier"); continue; }
  if (docType !== "OC" && docType !== "DN") { problem(fileName, "Unknown document type"); continue; }

  const documentNumber = pick("documentNumber");
  const docPo = pick("poNumber");
  const docDate = pick("deliveryDate");
  const pattern = supplier.codePattern ? new RegExp(supplier.codePattern, "g") : null;
  let lineCount = 0;

  for (const p of good) {
    const lines = p.answer.lines || [];
    const checkable = pattern && !first.isScan && p.req.pageText;

    // ---- Completeness check for this page (digital PDFs only) ----
    let inText = new Set();
    if (checkable) {
      inText = new Set((p.req.pageText.match(pattern) || []).map(norm));
      const inAnswer = new Set(lines.flatMap(l => [norm(l.supplierPartNo), norm(l.customerPartNo)]));
      const missing = [...inText].filter(c => !inAnswer.has(c));
      if (missing.length) {
        const list = missing.slice(0, 10).join(", ") + (missing.length > 10 ? ` (+${missing.length - 10})` : "");
        problem(fileName, `${pageLabel(p)}${missing.length} lines of the document are missing from the reading: ${list}`);
      }
    }

    for (const l of lines) {
      // Was this code really printed? (catches invented lines)
      let checkNote = "";
      if (checkable && !inText.has(norm(l.supplierPartNo)) && !inText.has(norm(l.customerPartNo))) {
        checkNote = `Code ${l.supplierPartNo || l.customerPartNo} does not appear in the document text`;
      }
      if (first.isScan && rulebook.ai.reviewScans) {
        checkNote = "Read from a scan – check visually";
      }

      lineCount++;
      output.push({
        json: {
          sourceFile: fileName,
          supplier: supplierKey,
          supplierName: supplier.name,
          docType: docType,
          documentNumber: documentNumber,
          poNumber: l.poNumber || docPo,              // line PO wins (several orders per DN)
          position: l.position,
          customerPartNo: l.customerPartNo,
          supplierPartNo: l.supplierPartNo,
          quantity: l.quantity,
          confirmedQuantity: l.confirmedQuantity,
          unit: l.unit,
          packSize: l.packSize,
          unitPrice: l.unitPrice,
          priceUnit: l.priceUnit,
          lineTotal: l.lineTotal,
          deliveryDate: l.deliveryDate || docDate,    // line date wins
          palletNo: l.palletNo,
          readBy: first.isScan ? "AI (scan)" : `AI (text, ${parts.length} ${parts.length > 1 ? "pages read separately" : "request"})`,
          checkNote: checkNote,
          status: "OK",
        },
      });
    }
  }
  if (lineCount === 0) problem(fileName, "AI found no lines");
}

return output;

// ============================================================
// SKIPPED FILES – files that were not read, and why.
// They go to Review.xlsx, so every uploaded file is accounted for.
// ============================================================

return $input.all().map(item => ({
  json: {
    sourceFile: item.json.fileName,
    status: item.json.fileKind === "duplicate"
      ? "Skipped: the same document was also uploaded as Excel (the Excel was read)"
      : "Skipped: unknown file type",
  },
}));
